import {escapeHTML as e,sanitize} from './store.js';

export function editorMarkup(note){return `<article class="note-editor"><div class="note-editor-head"><span class="eyebrow">SEU ESPAÇO DE ESCRITA</span><button id="expandEditor" class="focus-button" aria-label="Expandir editor" aria-expanded="false" title="Expandir editor"><span>⛶</span><span class="focus-label">Expandir</span></button></div><div class="editor-toolbar" aria-label="Formatação de texto"><select id="blockType" aria-label="Estilo do texto"><option value="p">Texto</option><option value="h1">Título 1</option><option value="h2">Título 2</option><option value="h3">Título 3</option><option value="blockquote">Citação</option></select><button data-format="bold" title="Negrito" aria-label="Negrito"><b>B</b></button><button data-format="italic" title="Itálico" aria-label="Itálico"><em>I</em></button><button data-format="underline" title="Sublinhado" aria-label="Sublinhado"><u>U</u></button><button data-format="strikeThrough" title="Tachado" aria-label="Tachado"><s>S</s></button><button data-format="insertUnorderedList" title="Lista com marcadores" aria-label="Lista com marcadores">☷</button><button data-format="insertOrderedList" title="Lista numerada" aria-label="Lista numerada">≡</button><button id="linkButton" title="Adicionar ou editar link" aria-label="Adicionar ou editar link">↗</button><details class="color-picker" id="colorPicker"><summary title="Cores do texto" aria-label="Cores do texto"><span class="color-symbol">A</span><span>⌄</span></summary><div class="color-panel"><span class="eyebrow">COR DO TEXTO</span><div class="color-presets">${[['#344b3c','Floresta'],['#9b7846','Âmbar'],['#a84e52','Rosa antigo'],['#416c99','Azul'],['#7b5f9a','Lavanda'],['#4c827c','Petróleo'],['#687278','Ardósia'],['#c6a6d9','Lilás claro']].map(([color,name])=>`<button type="button" data-color="${color}" style="--swatch:${color}" title="${name}" aria-label="${name}"></button>`).join('')}</div><button type="button" id="defaultColor" class="default-color">Cor padrão do tema</button><label class="custom-color"><span>Personalizar</span><input type="color" id="textColor" value="#9b7846" aria-label="Cor personalizada"></label></div></details><button data-format="removeFormat" title="Limpar formatação" aria-label="Limpar formatação">T×</button><span class="toolbar-divider"></span><button data-format="undo" title="Desfazer" aria-label="Desfazer">↶</button><button data-format="redo" title="Refazer" aria-label="Refazer">↷</button></div><input class="note-title" id="noteTitle" value="${e(note.title)}" aria-label="Título do documento"><div id="editor" class="editable" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Conteúdo do documento" data-placeholder="Comece uma história…">${sanitize(note.body)}</div><div class="editor-bottom"><span id="wordCount"></span><button class="text-link" data-action="deleteNote">Excluir documento</button></div></article>`;}

export function mountEditor(note,{onChange,onTitle,notify}){
  const editor=document.querySelector('#editor'),toolbar=document.querySelector('.editor-toolbar'),styleSelect=document.querySelector('#blockType');
  const controller=new AbortController(),options={signal:controller.signal};let savedRange=null,focusTimer;
  const count=()=>document.querySelector('#wordCount').textContent=`${(editor.textContent.trim().match(/\S+/g)||[]).length} palavras · Salvamento automático`;
  function capture(){const selection=getSelection();if(selection.rangeCount&&editor.contains(selection.getRangeAt(0).commonAncestorContainer)){savedRange=selection.getRangeAt(0).cloneRange();return true;}return false;}
  function restore(){editor.focus({preventScroll:true});if(savedRange&&editor.contains(savedRange.commonAncestorContainer)){const selection=getSelection();selection.removeAllRanges();selection.addRange(savedRange);}else{const r=document.createRange();r.selectNodeContents(editor);r.collapse(false);getSelection().removeAllRanges();getSelection().addRange(r);}}
  function change(){note.body=sanitize(editor.innerHTML);note.updated=new Date().toISOString();count();onChange();capture();}
  function sync(){if(!capture())return;const selection=getSelection();let node=selection.anchorNode?.nodeType===1?selection.anchorNode:selection.anchorNode?.parentElement;const block=node?.closest('h1,h2,h3,blockquote,p,div');if(document.activeElement!==styleSelect)styleSelect.value=block&&block!==editor&&/^(H[123]|BLOCKQUOTE)$/.test(block.tagName)?block.tagName.toLowerCase():'p';toolbar.querySelectorAll('[data-format]').forEach(button=>{if(['bold','italic','underline','strikeThrough'].includes(button.dataset.format))button.setAttribute('aria-pressed',String(document.queryCommandState(button.dataset.format)));});}
  function command(name,value){restore();document.execCommand('styleWithCSS',false,false);document.execCommand(name,false,value);change();sync();}
  document.execCommand('defaultParagraphSeparator',false,'p');
  editor.addEventListener('input',change,options);editor.addEventListener('paste',event=>{event.preventDefault();document.execCommand('insertText',false,event.clipboardData.getData('text/plain'));},options);
  document.querySelector('#noteTitle').oninput=event=>{note.title=event.target.value||'Sem título';note.updated=new Date().toISOString();onTitle();};
  document.addEventListener('selectionchange',sync,options);
  toolbar.addEventListener('pointerdown',event=>{capture();if(event.target.closest('button'))event.preventDefault();},options);
  toolbar.querySelectorAll('[data-format]').forEach(button=>button.onclick=()=>command(button.dataset.format));
  styleSelect.onchange=()=>{const value=styleSelect.value;command('formatBlock',value);styleSelect.value=value;};
  toolbar.querySelectorAll('[data-color]').forEach(button=>button.onclick=()=>{command('foreColor',button.dataset.color);document.querySelector('#colorPicker').open=false;});
  document.querySelector('#textColor').oninput=event=>command('foreColor',event.target.value);
  document.querySelector('#defaultColor').onclick=()=>{restore();document.execCommand('foreColor',false,'inherit');change();document.querySelector('#colorPicker').open=false;};
  document.addEventListener('pointerdown',event=>{if(!event.target.closest('#colorPicker'))document.querySelector('#colorPicker').open=false;},options);
  document.querySelector('#linkButton').onclick=()=>{
    restore();capture();const selection=getSelection();const anchor=(selection.anchorNode?.nodeType===1?selection.anchorNode:selection.anchorNode?.parentElement)?.closest('a');if(anchor&&editor.contains(anchor)){savedRange=document.createRange();savedRange.selectNode(anchor);}
    const selected=anchor?.textContent||selection.toString();const dialog=document.createElement('dialog');dialog.className='link-dialog';dialog.innerHTML=`<form><div class="modal-head"><div><span class="eyebrow">CONECTE SUAS IDEIAS</span><h2>${anchor?'Editar link':'Adicionar link'}</h2></div><button type="button" class="icon-button" aria-label="Fechar link">×</button></div><label class="field"><span>Texto do link</span><input name="text" value="${e(selected)}" placeholder="Como o link vai aparecer" maxlength="500"></label><label class="field"><span>Endereço</span><input name="url" value="${e(anchor?.getAttribute('href')||'')}" placeholder="https://exemplo.com" required><small class="help">Sites e endereços de e-mail (mailto:).</small></label><p class="link-error" role="alert"></p><div class="modal-actions">${anchor?'<button type="button" class="button ghost unlink-button">Remover link</button>':''}<button type="button" class="button ghost cancel-link">Cancelar</button><button class="button" type="submit">${anchor?'Salvar link':'Inserir link'}</button></div></form>`;document.body.append(dialog);dialog.showModal();const close=()=>{dialog.close();dialog.remove();restore();};dialog.querySelector('.icon-button').onclick=close;dialog.querySelector('.cancel-link').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.querySelector('.unlink-button')?.addEventListener('click',()=>{dialog.close();command('unlink');close();});dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target);let url=String(data.get('url')).trim();if(!/^[a-z][\w+.-]*:/i.test(url))url='https://'+url;try{const parsed=new URL(url);if(!['https:','http:','mailto:'].includes(parsed.protocol)||(['https:','http:'].includes(parsed.protocol)&&!parsed.hostname.includes('.')))throw Error();}catch{dialog.querySelector('.link-error').textContent='Informe um endereço válido, como https://exemplo.com.';return;}const text=String(data.get('text')).trim()||selected||url;dialog.close();restore();document.execCommand('insertHTML',false,`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(text)}</a>`);change();close();};
  };
  const expand=document.querySelector('#expandEditor'),layout=document.querySelector('.editor-layout');
  function toggleFocus(){const open=!layout.classList.contains('editor-expanded');clearTimeout(focusTimer);if(open){layout.classList.remove('editor-contracting');layout.classList.add('editor-expanded');document.body.classList.add('writing-focus');}else{layout.classList.add('editor-contracting');focusTimer=setTimeout(()=>{layout.classList.remove('editor-expanded','editor-contracting');document.body.classList.remove('writing-focus');},200);}expand.setAttribute('aria-expanded',String(open));expand.setAttribute('aria-label',open?'Restaurar editor':'Expandir editor');expand.title=open?'Restaurar editor':'Expandir editor';expand.querySelector('.focus-label').textContent=open?'Restaurar':'Expandir';}
  expand.onclick=toggleFocus;document.addEventListener('keydown',event=>{if(event.key==='Escape'&&layout.classList.contains('editor-expanded')&&!document.querySelector('dialog[open]'))toggleFocus();},options);count();
  return()=>{controller.abort();clearTimeout(focusTimer);document.body.classList.remove('writing-focus');document.querySelector('.link-dialog')?.remove();};
}
